class InvalidAgeError(Exception):
    pass

def set_age(age):
    if age < 0:
        raise InvalidAgeError(f'Age cannot be negative: {age}')
    return age

try:
    set_age(-5)
except InvalidAgeError as e:
    print(f'Caught: {e}')

def risky(value):
    return 10 / int(value)

for value in ['2', '0', 'abc']:
    try:
        print(risky(value))
    except ZeroDivisionError:
        print('No division by zero!')
    except ValueError:
        print('Invalid value!')

settings = {'host': 'localhost'}

def get_port():
    try:
        return settings['port']
    except KeyError as e:
        raise ValueError(f'Key not found: {e}') from e

try:
    get_port()
except ValueError as e:
    print(e)
    print('Original cause:', repr(e.__cause__))

def validate_username(name):
    if not (3 <= len(name) <= 20):
        raise ValueError('Username must be 3-20 characters')
    if not name.isalnum():
        raise ValueError('Only letters and numbers allowed')
    return name

for candidate in ['alice99', 'ab', 'bad name!', 'x' * 25]:
    try:
        print(f'Valid: {validate_username(candidate)}')
    except ValueError as e:
        print(f'Invalid: {e}')

import warnings

def new_greet(name):
    return f'Hello, {name}!'

def old_greet(name):
    warnings.warn('old_greet() is deprecated, use new_greet()', DeprecationWarning, stacklevel=2)
    return new_greet(name)

warnings.simplefilter('always')
print(old_greet('Sam'))

